  emass2 = 1021997.8125
  api = arccos((-1.0))
  bbconst = 16.0 * api * a0 * a0 * ry * ry / emass2
  ampion = 1.2000000476837158
  # CONSTANTS FOR IONISATION
  am2 = 12.755000114440918
  c = 146.1999969482422
  nasize = 4000
  nbrem = 25
  nion = 4
  natt = 5
  nin = 29
  nnull = 0
  fdo j, 1, nin:
    izbr[j] = 0
  izbr[nin + 1] = 6
  izbr[nin + 2] = 9
  # USE OKHRIMOVSKKY FOR ELASTIC AND IONISATION
  fdo j, 1, 6:
    kel[j] = 2
  # USE OKHRIMOVSKKY FOR INELASTICS
  fdo j, 1, nin:
    kin[j] = 2
  nel = 131
  nvibl = 19
  nvibh = 19
  nvibm = 18
  n3bp1 = 16
  n3bp2 = 14
  ntrp1 = 12
  ntrp2 = 11
