  ev[6] = 0.0
  eion[1] = 11.0
  eion[2] = 38.0
  eion[3] = 285.0
  eion[4] = 685.4000244140625
  # OPAL BEATY
  fdo l, 1, nion:
    eoby[l] = 11.5
  # CALCULATE AUGER FLUORESCENCE AND DOUBLE CHARGE STATE PARAMETERS
  fdo jk, 1, nion:
    legas[jk] = 0
    ishell[jk] = 0
