  # K-SHELL CARBON
  legas[3] = 1
  ishell[3] = 1
  nc0[3] = 2
  ec0[3] = 253.0
  wklm[3] = 0.0026000000070780516
  efl[3] = 273.0
  ng1[3] = 1
  eg1[3] = 253.0
  ng2[3] = 2
  eg2[3] = 5.0
  # K-SHELL FLUORINE
  legas[4] = 2
  ishell[4] = 1
  nc0[4] = 3
  ec0[4] = 625.2000122070312
  wklm[4] = 0.009999999776482582
  efl[4] = 668.0
  ng1[4] = 2
  eg1[4] = 625.2000122070312
  ng2[4] = 1
  eg2[4] = 5.0
  ein[1] = (-0.05000000074505806)
  ein[2] = (-0.10949999839067459)
  ein[3] = (-0.15000000596046448)
  ein[4] = (-0.21050000190734863)
  ein[5] = (-0.3100000023841858)
  ein[6] = (-0.3856000006198883)
  ein[7] = 0.05000000074505806
  ein[8] = 0.10949999839067459
  ein[9] = 0.15000000596046448
  ein[10] = 0.21050000190734863
  ein[11] = 0.3100000023841858
  ein[12] = 0.3856000006198883
  ein[13] = 0.024999000132083893
  ein[14] = 3.799999952316284
  ein[15] = 5.199999809265137
  ein[16] = 6.900000095367432
  ein[17] = 7.300000190734863
  ein[18] = 7.880000114440918
  ein[19] = 8.619999885559082
  ein[20] = 8.800000190734863
  ein[21] = 8.899999618530273
  ein[22] = 10.0
  ein[23] = 10.100000381469727
  ein[24] = 11.399999618530273
  ein[25] = 12.0
  ein[26] = 13.5
  ein[27] = 14.399999618530273
  ein[28] = 15.5
  ein[29] = 20.5
  # OFFSET ENERGY FOR IONISATION ELECTRON ANGULAR DISTRIBUTION
  fdo j, 1, nion:
    block L40:
      fdo i, 1, nasize:
        if mix2.eg[i] > eion[j]:
          ioffion[j] = i - 1
          break L40
  # OFFSET ENERGY FOR EXCITATION ANGULAR DISTRIBUTION
  fdo nl, 1, nin:
    block L50:
      fdo i, 1, nasize:
        if mix2.eg[i] > abs(ein[nl]):
          ioffn[nl] = i - 1
          break L50
  # ENTER PENNING TRANSFER FRACTION FOR EACH LEVEL
  # SET PENNING TRANSFER FRACTION TO ZERO FOR LOW LEVELS
  fdo k, 1, nin:
    fdo l, 1, 3:
      penfra[l, k] = 0.0
  # PENNING TRANSFER FRACTION FOR LEVELS ABOVE 6.0EV
  fdo k, 61, nin:
    penfra[1, k] = 0.0
    # PENNING TRANSFER DISTANCE IN MICRONS
    penfra[2, k] = 1.0
    # PENNING TRANSFER TIME IN PICOSECONDS
    penfra[3, k] = 1.0
    if not (inpt.ipen == 0):
      fwrite(fmt999, name, ein[k], penfra[1, k], penfra[2, k], penfra[3, k])
  scrpt[1] = fstr("                                                  ", 50)
  if inpt.naniso == 2:
    scrpt[2] = fstr(" ELASTIC   ANISOTROPIC HFO 1234ZE                 ", 50)
  elif inpt.naniso == 0:
    scrpt[2] = fstr(" ELASTIC     ISOTROPIC HFO 1234ZE                 ", 50)
  else:
    fwrite(fmt998)
    fstop()
  scrpt[3] = fstr(" IONISATION SUM OF SINGLE CHARGE   ELOSS=  11.0   ", 50)
  scrpt[4] = fstr(" IONISATION DOUBLE CHARGE STATES   ELOSS=  38.0   ", 50)
  scrpt[5] = fstr(" IONISATION    CARBON   K-SHELL    ELOSS= 285.0   ", 50)
  scrpt[6] = fstr(" IONISATION    FLUORINE K-SHELL    ELOSS= 685.4   ", 50)
  scrpt[7] = fstr(" ATTACHMENT THERMAL TO DIMERS                     ", 50)
  scrpt[8] = fstr(" ATTACHMENT  2 BODY DISSOCIATIVE F2H -            ", 50)
  scrpt[9] = fstr(" ATTACHMENT  2 BODY DISSOCIATIVE C3F3H -          ", 50)
  scrpt[10] = fstr(" ATTACHMENT  2 BODY DISSOCIATIVE F -              ", 50)
  scrpt[11] = fstr(" ATTACHMENT 3 BODY                                ", 50)
  scrpt[12] = fstr("                                                  ", 50)
  scrpt[13] = fstr("                                                  ", 50)
  scrpt[14] = fstr(" VIB    C-F BEND                   ELOSS= -0.050  ", 50)
  scrpt[15] = fstr(" VIB    C-C STRETCH                ELOSS= -0.1095 ", 50)
  scrpt[16] = fstr(" VIB    C-F STRETCH                ELOSS= -0.150  ", 50)
  scrpt[17] = fstr(" VIB    C=C STRETCH                ELOSS= -0.2105 ", 50)
  scrpt[18] = fstr(" VIB    2 * C-F STRETCH            ELOSS= -0.310  ", 50)
  scrpt[19] = fstr(" VIB    C-H STRETCH                ELOSS= -0.3856 ", 50)
  scrpt[20] = fstr(" VIB    C-F BEND                   ELOSS=  0.050  ", 50)
  scrpt[21] = fstr(" VIB    C-C STRETCH                ELOSS=  0.1095 ", 50)
  scrpt[22] = fstr(" VIB    C-F STRETCH                ELOSS=  0.150  ", 50)
  scrpt[23] = fstr(" VIB    C=C STRETCH                ELOSS=  0.2105 ", 50)
  scrpt[24] = fstr(" VIB    2 * C-F STRETCH            ELOSS=  0.310  ", 50)
  scrpt[25] = fstr(" VIB    C-H STRETCH                ELOSS=  0.3856 ", 50)
  scrpt[26] = fstr(" VIB   MODERATION        RESIDUAL ENERGY=  0.024999", 50)
  scrpt[27] = fstr(" 3B PI TRIPLET PART 1              ELOSS=  3.80   ", 50)
  scrpt[28] = fstr(" 3B PI TRIPLET PART 2              ELOSS=  5.20   ", 50)
  scrpt[29] = fstr(" 1B PI SINGLET PART 1  F=0.023     ELOSS=  6.90   ", 50)
  scrpt[30] = fstr(" 1B PI SINGLET PART 2  F=0.103     ELOSS=  7.30   ", 50)
  scrpt[31] = fstr(" 1B PI SINGLET PART 3  F=0.178     ELOSS=  7.88   ", 50)
  scrpt[32] = fstr(" 1B PI SINGLET PART 4  F=0.047     ELOSS=  8.62   ", 50)
  scrpt[33] = fstr(" NEUTRAL DISS   NON-DIPOLE         ELOSS=  8.8    ", 50)
  scrpt[34] = fstr(" NEUTRAL DISS   DIPOLE   F=0.06    ELOSS=  8.9    ", 50)
  scrpt[35] = fstr(" NEUTRAL DISS   NON-DIPOLE         ELOSS= 10.0    ", 50)
  scrpt[36] = fstr(" NEUTRAL DISS   DIPOLE   F=0.070   ELOSS= 10.1    ", 50)
  scrpt[37] = fstr(" NEUTRAL DISS   NON-DIPOLE         ELOSS= 11.4    ", 50)
  scrpt[38] = fstr(" NEUTRAL DISS   DIPOLE    F=0.13   ELOSS= 12.0    ", 50)
  scrpt[39] = fstr(" NEUTRAL DISS   DIPOLE    F=0.48   ELOSS= 13.5    ", 50)
  scrpt[40] = fstr(" NEUTRAL DISS   NON-DIPOLE         ELOSS= 14.4    ", 50)
  scrpt[41] = fstr(" NEUTRAL DISS   DIPOLE    F=5.27   ELOSS= 15.5    ", 50)
  scrpt[42] = fstr(" NEUTRAL DISS   DIPOLE    F=2.66   ELOSS= 20.5    ", 50)
  scrpt[43] = fstr(" BREMSSTRAHLUNG FROM HYDROGEN                     ", 50)
  scrpt[44] = fstr(" BREMSSTRAHLUNG FROM CARBON                       ", 50)
  scrpt[45] = fstr(" BREMSSTRAHLUNG FROM FLUORINE                     ", 50)
  # DENSITY CORERCTION FOR 3-BODY ATTACHMENT CROSS-SECTION
  # CRITICAL DENSITY : 31 TORR = ANCRIT
  # ANCRIT=31.0
  # FAC1=1.0/(ANCRIT/TORR+1.0)
  fac1 = 1.0
  fac = 293.1499938964844 * inpt.torr / ((inpt.tempc + 273.1499938964844) * 760.0)
  fac = fac * fac1
  # write(6,99) FAC,TORR,ANCRIT
  # 99  format(' FAC=',D12.4,' TORR=',D12.4' ncrit=',D12.4)
  # GROUPED VIBRATIONS SO NO DEGENERACY CALCULATION POSSIBLE
  # USED INDEPENDENT APPROXIMATION FOR UPPER STATE POPULATION
  apop1 = exp(ein[1] / inpt.akt)
  apop2 = exp(ein[2] / inpt.akt)
  apop3 = exp(ein[3] / inpt.akt)
  apop4 = exp(ein[4] / inpt.akt)
  apop5 = exp(ein[5] / inpt.akt)
  apop6 = exp(ein[6] / inpt.akt)
  # RENORMALISE GS POPULATION TO ACCOUNT FOR EXCITATION FROM EXCITED STATE
  apopgs = 1.0
  fdo i, 1, inpt.nstep:
    en = mix2.eg[i]
    gamma1 = (emass2 + 2.0 * en) / emass2
    gamma2 = gamma1 * gamma1
    beta = sqrt(1.0 - 1.0 / gamma2)
    beta2 = beta * beta
    # ELASTIC CALCULATION
    q[2, i] = 0.0
    block L20:
      if en <= xel[1]:
        qela = yel[1] * 1e-16
        qmmt = ymt[1] * 1e-16
        eps = yeps[1]
        break L20
      block L19:
        fdo j, 2, nel:
          if en <= xel[j]: break L19
        j = nel
      # USE LOG INTERPOLATION
      yxj = ln(yel[j])
      yxj1 = ln(yel[j - 1])
      xnj = ln(xel[j])
      xnj1 = ln(xel[j - 1])
      a = (yxj - yxj1) / (xnj - xnj1)
      b = (xnj1 * yxj - xnj * yxj1) / (xnj1 - xnj)
      qela = exp(a * ln(en) + b) * 1e-16
      yxj = ln(ymt[j])
      yxj1 = ln(ymt[j - 1])
      a = (yxj - yxj1) / (xnj - xnj1)
      b = (xnj1 * yxj - xnj * yxj1) / (xnj1 - xnj)
      qmmt = exp(a * ln(en) + b) * 1e-16
      # ANGULAR DISTRIBUTION FOR ELASTICS (OKHRIMOVSSKY)
      a = (yeps[j] - yeps[j - 1]) / (xel[j] - xel[j - 1])
      b = (xel[j - 1] * yeps[j] - xel[j] * yeps[j - 1]) / (xel[j - 1] - xel[j])
      eps = a * en + b
    # CONVERT TO (1.0-EPS)
    eps = 1.0 - eps
    if inpt.naniso == 2:
      # USE ELASTIC (ANISOTROPIC SCATTERING)
      q[2, i] = qela
      peqel[2, i] = eps
    elif inpt.naniso == 0:
      # USE ISOTROPIC MT ELASTIC
      q[2, i] = qmmt
      peqel[2, i] = 0.0
    else:
      fwrite(fmt996)
      fstop()
    # ZERO IONISATION ARRAYS
    fdo j, 1, nion:
      peqion[j, i] = 0.0
      qion[j, i] = 0.0
    block L190:
      # IF ENERGY GT 3 KEV USE OSCILLATOR STRENGTH FOR IONISATION
      # CALCULATE  COUNTING AND GROSS IONISATION
      if en < eion[1]: break L190
      block L145:
        block L140:
          if en > 3000.0: break L140
          block L103:
            fdo j, 2, nionc:
              if en <= xion[j]: break L103
            j = nionc
          x1 = ln(xion[j])
          x2 = ln(xion[j - 1])
          y1 = ln(yionc[j])
          y2 = ln(yionc[j - 1])
          a = (y1 - y2) / (x1 - x2)
          b = (x2 * y1 - x1 * y2) / (x2 - x1)
          qionc = exp(a * ln(en) + b) * 1e-16 * ampion
          y1 = ln(yiong[j])
          y2 = ln(yiong[j - 1])
          a = (y1 - y2) / (x1 - x2)
          b = (x2 * y1 - x1 * y2) / (x2 - x1)
          qiong = exp(a * ln(en) + b) * 1e-16 * ampion
          # TODO: VERIFY THAT QIONC/QIONG ARE USED
          # IN THE CALCULATION. DEGRAD DOESNT
          # IONISATION TO SINGLE CHARGE STATES
          if en > 3000.0: break L140
          block L107:
            fdo j, 2, nion1:
              if en <= xion1[j]: break L107
            j = nion1
          x1 = ln(xion1[j])
          x2 = ln(xion1[j - 1])
          y1 = ln(yion1[j])
          y2 = ln(yion1[j - 1])
          a = (y1 - y2) / (x1 - x2)
          b = (x2 * y1 - x1 * y2) / (x2 - x1)
          qion[1, i] = exp(a * ln(en) + b) * 1e-16 * ampion
          # IONISATION TO DOUBLE CHARGE STATES
          if en <= eion[2]: break L190
          if en > 3000.0: break L140
          block L111:
            fdo j, 2, nion2:
              if en <= xion2[j]: break L111
            j = nion2
          x1 = ln(xion2[j])
          x2 = ln(xion2[j - 1])
          y1 = ln(yion2[j])
          y2 = ln(yion2[j - 1])
          a = (y1 - y2) / (x1 - x2)
          b = (x2 * y1 - x1 * y2) / (x2 - x1)
          qion[2, i] = exp(a * ln(en) + b) * 1e-16 * ampion
          break L145
        # ENERGY ABOVE 3 KEV USE BORN-BETHE X-SECTION
        x2 = 1.0 / beta2
        x1 = x2 * ln(beta2 / (1.0 - beta2)) - 1.0
        qbb = `const` * (am2 * (x1 - dens.den[i] / 2.0) + c * x2)
        qionc = qbb
        qiong = qbb * 1.0485999584197998
        qion[1, i] = qionc * 0.9484000205993652 * ampion
        qion[2, i] = qionc * 0.051600001752376556 * ampion
      # CARBON K-SHELL IONISATION
      # FACTOR OF 3 FOR NUMBER OF CARBON ATOMS
      if en <= eion[3]: break L190
      block L147:
        fdo j, 2, nion3:
          if en <= xion3[j]: break L147
        j = nion3
      a = (yion3[j] - yion3[j - 1]) / (xion3[j] - xion3[j - 1])
      b = (xion3[j - 1] * yion3[j] - xion3[j] * yion3[j - 1]) / (xion3[j - 1] - xion3[j])
      qion[3, i] = (a * en + b) * 1e-16 * 3.0
      # FLUORINE K-SHELL IONISATION
      # FACTOR OF 4 FOR NUMBER OF FLUORINE ATOMS
      if not (en <= eion[4]):
        block L152:
          fdo j, 2, nion4:
            if en <= xion4[j]: break L152
          j = nion4
        a = (yion4[j] - yion4[j - 1]) / (xion4[j] - xion4[j - 1])
        b = (xion4[j - 1] * yion4[j] - xion4[j] * yion4[j - 1]) / (xion4[j - 1] - xion4[j])
        qion[4, i] = (a * en + b) * 1e-16 * 4.0
      # CORRECTION TO IONISATION DUE TO SPLIT INTO K-SHELLS
      ssum = qion[3, i] + qion[4, i]
      tot = qion[1, i] + qion[2, i]
      if tot == 0.0: break L190
      crfac = (tot - ssum) / tot
      fdo j, 1, nion - 2:
        qion[j, i] = qion[j, i] * crfac
    # IONISATION ANGULAR DISTRIBUTION
    fdo j, 1, nion:
      if not (en <= 2.0 * eion[j]):
        peqion[j, i] = peqel[2, i - ioffion[j]]
        # SET TO ISOTROPIC IF NANISO=0
        if inpt.naniso == 0: peqion[j, i] = 0.0
    sumion = qion[1, i] + qion[2, i] + qion[3, i] + qion[4, i]
    # ZERO ATTACHMENT
    fdo j, 1, natt:
      qatt[j, i] = 0.0
    # THERMAL ATTACHMENT TO DIMERS
    q[4, i] = 0.0
    qatt[1, i] = 0.0
    block L210:
      if en < xatt1[1]: break L210
      if en > xatt1[natt1]: break L210
      block L202:
        fdo j, 2, natt1:
          if en <= xatt1[j]: break L202
        j = natt1
      x1 = ln(xatt1[j])
      x2 = ln(xatt1[j - 1])
      y1 = ln(yatt1[j])
      y2 = ln(yatt1[j - 1])
      a = (y1 - y2) / (x1 - x2)
      b = (x2 * y1 - x1 * y2) / (x2 - x1)
      qatt[1, i] = exp(a * ln(en) + b) * 1e-16 * ampattherm
    block L220:
      # DISSOCIATIVE ATTACHMENT TO H2F -
      if en < xatt2[1]: break L220
      if en > xatt2[natt2]: break L220
      block L212:
        fdo j, 2, natt2:
          if en <= xatt2[j]: break L212
        j = natt2
      x1 = ln(xatt2[j])
      x2 = ln(xatt2[j - 1])
      y1 = ln(yatt2[j])
      y2 = ln(yatt2[j - 1])
      a = (y1 - y2) / (x1 - x2)
      b = (x2 * y1 - x1 * y2) / (x2 - x1)
      qatt[2, i] = exp(a * ln(en) + b) * 1e-16 * ampatt2b
    block L230:
      # DISSOCIATIVE ATTACHMENT TO C3F3H -
      if en < xatt3[1]: break L230
      if en > xatt3[natt3]: break L230
      block L222:
        fdo j, 2, natt3:
          if en <= xatt3[j]: break L222
        j = natt3
      x1 = ln(xatt3[j])
      x2 = ln(xatt3[j - 1])
      y1 = ln(yatt3[j])
      y2 = ln(yatt3[j - 1])
      a = (y1 - y2) / (x1 - x2)
      b = (x2 * y1 - x1 * y2) / (x2 - x1)
      qatt[3, i] = exp(a * ln(en) + b) * 1e-16 * ampatt2b
    block L240:
      # DISSOCIATIVE ATTACHMENT TO F -
      if en < xatt4[1]: break L240
      if en > xatt4[natt4]: break L240
      block L232:
        fdo j, 2, natt4:
          if en <= xatt4[j]: break L232
        j = natt4
      x1 = ln(xatt4[j])
      x2 = ln(xatt4[j - 1])
      y1 = ln(yatt4[j])
      y2 = ln(yatt4[j - 1])
      a = (y1 - y2) / (x1 - x2)
      b = (x2 * y1 - x1 * y2) / (x2 - x1)
      qatt[4, i] = exp(a * ln(en) + b) * 1e-16 * ampatt2b
    # ATTACHMENT 3 BODY
    # FOR MIXTURE DATA FURTHER SCALING NECESSARY USE FACTOR T3B
    # FOR SCALING IN PURE GAS USE T3B=1.0
    t3b = 1.0
    # CO2HFO 80/20   =0.2
    # T3B=0.20
    # CO2HFO 50/50   = 0.50
    # T3B=1.0
    # T3B=0.5
    # SCALING FACTOR PROPORTIONAL TO C3F8 FRACTION IN NOBLE GAS MIXTURES
    qatt[5, i] = 0.0
    block L250:
      if en < xatt5[1]: break L250
      if en > xatt5[natt5]: break L250
      block L242:
        fdo j, 2, natt5:
          if en <= xatt5[j]: break L242
        j = natt5
      x1 = ln(xatt5[j])
      x2 = ln(xatt5[j - 1])
      y1 = ln(yatt5[j])
      y2 = ln(yatt5[j - 1])
      a = (y1 - y2) / (x1 - x2)
      b = (x2 * y1 - x1 * y2) / (x2 - x1)
      qatt[5, i] = exp(a * ln(en) + b) * 1e-16 * fac * t3b * ampatt3b
    q[5, i] = 0.0
    q[6, i] = 0.0
    # ZERO INELASTIC ARRAYS
    fdo l, 1, nin:
      qin[l, i] = 0.0
      peqin[l, i] = 0.0
    # SUPERELASTIC OF C-C STRETCH
    efac = sqrt(1.0 - ein[1] / en)
    qin[1, i] = 1.0 * ln((efac + 1.0) / (efac - 1.0)) / en * ampv1
    # SUPERELASTIC OF C-C STRETCH RESONANCE 1.8 EV
    qresl = 0.0
    block L313:
      if en - ein[1] <= xvibl[1]: break L313
      if en - ein[1] > xvibl[nvibl]: break L313
      block L312:
        fdo j, 2, nvibl:
          if en - ein[1] <= xvibl[j]: break L312
        j = nvibl
      x1l = ln(xvibl[j])
